"""The Pi vectors of pi-ai's ``Type`` (test/parity/sdk-vectors/pi-ai/Type.json, generated by automation/gen/generate-sdk-vectors.mjs) resolved through the SDK's ``Type``: shared by the
pytest module (test_pi_ai_type_vectors.py) and by run_engine_vectors.py, which runs the cases the host's type engine answers through a real host (no pytest needed)."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Optional

from pig_sdk import BigInt, TSchema, TSchemaArray, Type

VECTORS = Path(__file__).resolve().parents[3] / "test" / "parity" / "sdk-vectors" / "pi-ai" / "Type.json"


def snake(name: str) -> str:
    if name == "With":
        return "with_"
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()


def predicate(spec: dict):
    """The predicate or message function a case names (the generator's predicateFor builds the same from the same spec)."""
    name = spec["$fn"]
    if name == "always":
        return lambda value: True
    if name == "never":
        return lambda value: False
    if name == "lengthAtLeast":
        return lambda value: len(str(value)) >= spec["n"]
    if name == "equals":
        return lambda value: value == spec["value"]
    if name == "even":
        return lambda value: value % 2 == 0
    if name == "greaterThan":
        return lambda value: value > spec["n"]
    if name in ("throws", "throwsText", "errorThrows"):
        def raises(value):
            raise RuntimeError(spec["message"])
        return raises
    if name == "text":
        return lambda value: spec["text"]
    if name == "textWithValue":
        return lambda value: spec["prefix"] + str(value)
    raise AssertionError(f"no predicate {name}")


def resolve(node: Any) -> Any:
    if isinstance(node, list):
        return [resolve(item) for item in node]
    if isinstance(node, dict):
        if node.get("$") == "bigint":
            return BigInt(int(node["value"]))
        if isinstance(node.get("$fn"), str):
            return predicate(node)
        if isinstance(node.get("$call"), str):
            return getattr(Type, snake(node["$call"]))(*[resolve(arg) for arg in node["args"]])
        return {key: resolve(value) for key, value in node.items()}
    return node


# The members of Type the host's type engine serves (pig_sdk/type_engine.py): calling one needs a host, which a unit test cannot reach. The same cases run through the host socket
# (TestConformance_TypeEngineMembersAgreeAcrossSDKs) and through the Go SDK's fused path (TestTypeEngineMembersMatchPi).
ENGINE_MEMBERS = {
    "Call", "Capitalize", "Conditional", "Constructor", "ConstructorParameters", "Cyclic", "Dependent", "Evaluate", "Exclude", "Extends", "Extract", "Function", "Generic",
    "Identifier", "Index", "Infer", "InstanceType", "Instantiate", "Interface", "KeyOf", "Lowercase", "Mapped", "Module", "NonNullable", "Omit", "Parameter", "Parameters",
    "Partial", "Pick", "ReadonlyObject", "ReadonlyType", "RecordKey", "RecordPattern", "RecordValue", "Required", "Rest", "ReturnType", "Script", "TemplateLiteral", "This",
    "Tuple", "Uncapitalize", "Uppercase",
}


def all_cases() -> list[dict]:
    cases = json.loads(VECTORS.read_text(encoding="utf-8"))["cases"]
    assert cases, "Type.json has no cases"
    return cases


def needs_host(case: dict) -> bool:
    node = case["args"][0]
    if case["name"] == "conformance engine tool parameters" or node.get("$call") in ENGINE_MEMBERS:
        return True
    # A Record whose key TypeBox evaluates with its type engine (an enum, an intersection or a template literal).
    if node.get("$call") == "Record":
        key = node["args"][0]
        return isinstance(key, dict) and key.get("$call") in ("Enum", "Intersect", "TemplateLiteral")
    return False


def non_engine_cases() -> list[dict]:
    return [case for case in all_cases() if not needs_host(case)]


def check_case(case: dict) -> Optional[str]:
    """What the SDK answers for one vector case against Pi's: the thrown message, the schema's JSON text and hidden members (or the TypeError writing it as JSON raises, for a schema
    that holds a bigint), or the guard's boolean. None is a match, otherwise the difference."""
    name = case["name"]
    try:
        got = resolve(case["args"][0])
    except Exception as error:  # noqa: BLE001 - the case may be one that throws, as Pi does
        if "throws" in case:
            return None if str(error) == case["throws"] else f"{name}: raised {str(error)!r}, Pi throws {case['throws']!r}"
        return f"{name}: raised {type(error).__name__}: {error}, Pi answers {case.get('result')}"
    if "throws" in case:
        return f"{name}: answered {got!r}, Pi throws {case['throws']!r}"
    want = case["result"]
    if isinstance(got, (TSchema, TSchemaArray)):
        if not (isinstance(want, dict) and ("json" in want or "stringifyThrows" in want)):
            return f"{name}: the SDK answers a schema, Pi {want}"
        if "stringifyThrows" in want:
            # The value holds a bigint: building it is fine, writing it as JSON is what throws, with Pi's message.
            try:
                text = got.to_json()
            except TypeError as error:
                if str(error) != want["stringifyThrows"]:
                    return f"{name}: writing it as JSON raised {str(error)!r}, Pi {want['stringifyThrows']!r}"
            else:
                return f"{name}: wrote {text}, Pi's JSON.stringify throws {want['stringifyThrows']!r}"
        elif got.to_json() != want["json"]:
            return f"{name}:\n got {got.to_json()}\n Pi  {want['json']}"
        hidden = {key: ({"count": len(value)} if key == "~refine" else value) for key, value in got.hidden.items()}
        if hidden != want["hidden"]:
            return f"{name}: hidden members {hidden}, Pi {want['hidden']}"
        return None
    if got != want or type(got) is not type(want):
        return f"{name}: {got!r}, Pi {want!r}"
    return None
